/**
 * The uses index (Wave 1 stage 0, task K3-1): every claim id a lesson renders through a token or a statline chip, with the
 * lesson, block type and field, generated by scripts/gen-lesson-claims.ts.
 */
import { describe, expect, test } from 'bun:test'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import type { ClaimUse } from '../../src/data/claims/uses'
import { useByClaim } from '../../src/data/claims/uses'

const ROOT = path.resolve(import.meta.dir, '../..')
const FILE = path.join(ROOT, 'src/data/claims/uses.generated.json')
const USES = JSON.parse(readFileSync(FILE, 'utf8')) as Record<string, ClaimUse[]>

describe('the uses index', () => {
  test('it is what the generator writes', async () => {
    const { renderUses } = await import('../../scripts/gen-lesson-claims')
    expect(readFileSync(FILE, 'utf8')).toBe(renderUses())
  })

  test('the block-size claim names every lesson that renders it', () => {
    const BLOCK = 'production.vllm.block-size'
    const places = USES[BLOCK] ?? []
    const at = (lesson: string, block: string, field: string) => places.some((p) => p.lesson === lesson && p.block === block && p.field === field)
    expect(at('t1.l4', 'prose', 'md')).toBe(true)
    expect(at('t1.l4', 'callout', 'md')).toBe(true)
    expect(at('t2.l7', 'isomorphism', 'breaks')).toBe(true)
    expect(at('t5.l5', 'prose', 'md')).toBe(true)
    expect(at('t5.l6', 'prose', 'md')).toBe(true)
    expect(useByClaim(BLOCK).length).toBe(places.length)
  })

  test('every id is a real claim and every use names a lesson', () => {
    for (const [id, places] of Object.entries(USES)) {
      expect(id).toMatch(/^[a-z0-9-]+(\.[a-z0-9-]+)+$/)
      expect(places.length).toBeGreaterThan(0)
      for (const p of places) {
        expect(p.lesson).toMatch(/^(r|t[0-7])\.l\d{1,2}$/)
        expect(p.field.length).toBeGreaterThan(0)
      }
    }
  })
})
